const obligationsOf=(c:LabelContract)=>c.obligations?.length?c.obligations.map(o=>({...o})) : []
function deliveryStatus(c:LabelContract){
 const rows=obligationsOf(c)
 if(!rows.length)return {label:'Suivi historique limité',tone:'neutral',progress:0,remaining:Math.max(0,c.remainingProjects??0),pace:0,detail:'Le détail par format n’est pas disponible pour ce contrat.'}
 const required=rows.reduce((n,o)=>n+Math.max(0,o.required),0)
 const remaining=rows.reduce((n,o)=>n+Math.max(0,o.remaining),0)
 const delivered=Math.max(0,required-remaining)
 const duration=Math.max(1,(c.years||1)*52)
 const weeksLeft=Math.max(0,c.remainingWeeks??duration)
 const elapsed=Math.max(0,Math.min(duration,duration-weeksLeft))
 const progress=required?delivered/required:1
 const expected=elapsed/duration
 const pace=weeksLeft>0?remaining/weeksLeft:0
 if(remaining===0)return {label:'Engagements remplis',tone:'good',progress:100,remaining,pace,detail:'Toutes les livraisons prévues ont été réalisées.'}
 if(weeksLeft===0)return {label:'Engagements non remplis',tone:'risk',progress:Math.round(progress*100),remaining,pace,detail:'Le contrat est arrivé à échéance avec des livraisons encore dues.'}
 if(progress+0.2<expected)return {label:'Retard important',tone:'risk',progress:Math.round(progress*100),remaining,pace,detail:'Le rythme actuel est inférieur au calendrier théorique du contrat.'}
 if(progress+0.08<expected)return {label:'À surveiller',tone:'watch',progress:Math.round(progress*100),remaining,pace,detail:'Un rythme de sortie plus soutenu sera nécessaire pour tenir les engagements.'}
 return {label:'Rythme cohérent',tone:'good',progress:Math.round(progress*100),remaining,pace,detail:'Les livraisons avancent à un rythme compatible avec la durée du contrat.'}
}
